c.save()
c=canvas.Canvas(str(R/'downloads/time-blocking-template.pdf'),pagesize=landscape(letter));c.setTitle('Weekly Time-Blocking Template - Blank Seven-Day Writing Grid');c.setAuthor('NexalyPlanner')
for pg,days in enumerate([['Monday','Tuesday','Wednesday'],['Thursday','Friday','Saturday','Sunday']],1):
 header(c,'Weekly time-blocking template','Week starting Monday: ____________  |  Fixed writing window 09:00-17:00',792,612,pg)
 c.setFont('D4',9);c.drawString(36,478,'Mark focus / fixed / break / buffer. Include preparation and travel; resolve overlaps.')
 left=90;right=756;top=440;bottom=132;cw=(right-left)/len(days);rh=(top-bottom)/8
 c.setStrokeColor(line);c.setFont('D4B',10)
 for i,day in enumerate(days):c.drawString(left+i*cw+8,top+17,day)
 for i in range(len(days)+1):c.line(left+i*cw,top,left+i*cw,bottom)
 c.setFont('D4',9)
 for i in range(9):
  y=top-i*rh;c.line(left,y,right,y);c.drawString(36,y-4,f'{9+i:02d}:00')
 c.drawString(36,91,'Priority / next change: _____________________________________________________________');c.drawString(36,66,'A block reserves time; it does not prove completion or check other people\'s availability.')
